	// R|                  "offset"), names(mf), 0)
	// R|     mf <- mf[c(1, m)]
	// R|     mf$drop.unused.levels <- TRUE
	// R|     mf[[1]] <- as.name("model.frame")
	// R|     mf <- eval.parent(mf)
	// R|     ##	  if (method == "model.frame") return(mf)
