const rtdal006213Source0158 = `all.eq.mod <- function(m1, m2, sub=FALSE, excl = c("call", "ctrl"), ...) {
    nm1 <- names(m1)
    stopifnot(if(sub) nm1 %in% names(m2) else nm1 == names(m2))
    ni <- if(sub)
	      nm1[is.na(match(nm1, c("call","ctrl")))]
	  else is.na(match(names(m1), excl))## <<- all but those with names in 'excl'
    all.equal(m1[ni], m2[ni], ...)
}`

const rtdal006213Source0160 = `fMM <- robustbase:::nlrob.MM(form, data = DNase1,
           lower = setNames.(0, pnms), upper = 3,
           ## call to nlrob.control to pass 'optim.control':
           ctrl = nlrob.control("MM", optim.control = list(trace = 1),
                                optArgs = list(trace = TRUE)))`

const rtdal006213Source0162 = "if(doExtras) {\n    ftau <- robustbase:::nlrob.tau(form, data = DNase1,\n                                   lower= setNames.(0, pnms), upper= 3,  trace=TRUE)\n    ##\n    fCM  <- robustbase:::nlrob.CM (form, data = DNase1,\n                                   lower= setNames.(0, psNms), upper= 3, trace=TRUE)\n    ##\n    fmtl <- robustbase:::nlrob.mtl(form, data = DNase1,\n                                   lower= setNames.(0, psNms), upper= 3, trace=TRUE)\n    ##\n    mods <- list(MM=fMM, tau=ftau, CM=fCM, MTL=fmtl)\n    print(sts <- sapply(mods, `[[`, \"status\"))\n    stopifnot(sts == \"converged\")\n\n    print(sapply(mods, `[[`, \"data\"))   # currently 'language' %% FIXME\n\n    print(sapply(mods, `[[`, \"coefficients\")) # nice matrix\n    showProc.time()\n}"

const rtdal006213Source0167 = `if(doExtras) {
### Now call the above methods via nlrob():
set.seed(47) # (same as above)
## without "sigma"
gMM  <- nlrob(form, data = DNase1, method = "MM",
              lower = setNames(c(0,0,0), pnms), upper = 3)
gtau <- nlrob(form, data = DNase1, method = "tau",
              lower = setNames(c(0,0,0), pnms), upper = 3)
## those with "sigma" -> must be in (lower, upper), too :
gCM  <- nlrob(form, data = DNase1, method = "CM",
              lower = setNames(c(0,0,0,0), psNms), upper = 3)
gmtl  <- nlrob(form, data = DNase1, method = "mtl",
              lower = setNames(c(0,0,0,0), psNms), upper = 3)
showProc.time()

## list {and test print(<nlrob>) for these}:
(mod2 <- list(MM=gMM, tau=gtau, CM=gCM, MTL=gmtl))

    stopifnot(mapply(all.eq.mod, mods, mod2, sub=TRUE))
}`

