const rtdal006279Source0002 = `assets_download <- function(items,
                            asset_names = NULL,
                            output_dir = getwd(),
                            overwrite = FALSE, ...,
                            use_gdal = FALSE,
                            download_fn = NULL) {
  # check output dir
  if (!dir.exists(output_dir))
    .error(paste("The directory provided does not exist.",
                 "Please, provide an existing directory."))
  UseMethod("assets_download", items)
}`

const rtdal006279Source0003 = `assets_download.doc_item <- function(items,
                                     asset_names = NULL,
                                     output_dir = getwd(),
                                     overwrite = FALSE, ...,
                                     use_gdal = FALSE,
                                     create_json = FALSE,
                                     download_fn = NULL) {
  if (!is.null(asset_names)) {
    in_assets <- asset_names %in% items_assets(items)
    if (!all(asset_names %in% items_assets(items))) {
      .warning("Item does not have asset(s) '%s'.",
               paste(asset_names[!in_assets], collapse = ", "))
    }
    items <- assets_select(items = items, asset_names = asset_names)
  }
  items$assets <- lapply(
    items$assets, asset_download, output_dir = output_dir,
    overwrite = overwrite, use_gdal = use_gdal, download_fn = download_fn, ...
  )
  if (create_json) {
    file <- "item.json"
    if ("id" %in% names(items)) {
      file <- paste0(items$id, ".json")
    }
    cat(to_json(items), file = file.path(output_dir, file))
  }
  items
}`

const rtdal006279Source0004 = `assets_download.doc_items <- function(items,
                                      asset_names = NULL,
                                      output_dir = getwd(),
                                      overwrite = FALSE, ...,
                                      use_gdal = FALSE,
                                      download_fn = NULL,
                                      create_json = TRUE,
                                      items_max = Inf,
                                      progress = TRUE) {
  # remove empty items
  items <- items_compact(items)
  items_max <- max(0, min(items_length(items), items_max))
  # verify if progress bar can be shown
  progress <- progress && items_max > 1
  if (progress) {
    pb <- utils::txtProgressBar(max = items_max, style = 3)
    # close progress bar when exit
    on.exit(if (progress) close(pb))
  }
  items$features <- items$features[seq_len(items_max)]
  for (i in seq_len(items_max)) {
    if (progress)
      utils::setTxtProgressBar(pb, i)
    items$features[[i]] <- assets_download(
      items = items$features[[i]], asset_names = asset_names,
      output_dir = output_dir, overwrite = overwrite,
      use_gdal = use_gdal, create_json = FALSE, download_fn = download_fn, ...
    )
  }
  if (create_json)
    cat(to_json(items), file = file.path(output_dir, "items.json"))
  items
}`

const rtdal006279Source0010 = `assets_select <- function(items, ..., asset_names = NULL, select_fn = NULL) {
  UseMethod("assets_select", items)
}`

const rtdal006279Source0011 = "assets_select.doc_item <- function(items, ...,\n                                   asset_names = NULL,\n                                   select_fn = NULL) {\n  exprs <- as.list(substitute(list(...), env = environment()))[-1]\n  init_length <- length(items$assets)\n  if (!is.null(asset_names)) {\n    asset_names <- intersect(names(items$assets), asset_names)\n    items$assets <- items$assets[asset_names]\n  }\n  if (length(exprs) > 0) {\n    if (!is.null(names(exprs)))\n      .error(\"Select expressions cannot be named.\")\n    for (expr in exprs) {\n      expr <- unquote(expr = expr, env =  parent.frame())\n      sel <- map_lgl(names(items$assets), function(key) {\n        select_eval(key = key, asset = items$assets[[key]], expr = expr)\n      })\n      items$assets <- items$assets[sel]\n    }\n  }\n  if (!is.null(select_fn)) {\n    sel <- map_lgl(names(items$assets), function(key) {\n      val <- select_exec(key = key, asset = items$assets[[key]],\n                         select_fn = select_fn)\n      return(val)\n    })\n    items$assets <- items$assets[sel]\n  }\n  if (length(items$assets) == 0 && init_length > 0)\n    .warning(paste(\"Filter criteria did not match any asset.\\n\",\n                   \"Please, see `?assets_select` for more details on\",\n                   \"how expressions are evaluated by `assets_select()`.\"))\n  items\n}"

const rtdal006279Source0012 = `assets_select.doc_items <- function(items, ...,
                                    asset_names = NULL,
                                    select_fn = NULL) {
  items <- foreach_item(
    items, assets_select, asset_names = asset_names, ...,
    select_fn = select_fn
  )
  return(items)
}`

const rtdal006279Source0014 = `assets_rename <- function(items, mapper = NULL, ...) {
  UseMethod("assets_rename", items)
}`

const rtdal006279Source0015 = "assets_rename.doc_item <- function(items, mapper = NULL, ...) {\n  dots <- list(...)\n  if (is.function(mapper)) {\n    new_names <- as.list(map_chr(items$assets, mapper, use_names = TRUE))\n  } else {\n    new_names <- as.list(mapper)\n  }\n  if (length(dots) > 0) {\n    new_names <- modify_list(new_names, dots)\n  }\n  new_names <- unlist(new_names)\n  if (length(new_names) == 0) {\n    .error(\"Parameters `mapper` or `...` must be informed.\")\n  }\n  if (!all(nzchar(names(new_names)))) {\n    .error(\"Parameters `mapper` and `...` must contains named values.\")\n  }\n  asset_names <- names(items$assets)\n  # remove empty names\n  new_names <- new_names[nzchar(new_names)]\n  asset_names[asset_names %in% names(new_names)] <-\n    unname(new_names[asset_names[asset_names %in% names(new_names)]])\n  names(items$assets) <- asset_names\n\n  return(items)\n}"

const rtdal006279Source0016 = `assets_rename.doc_items <- function(items, mapper = NULL, ...) {
  return(foreach_item(items, assets_rename, mapper = mapper, ...))
}`

