const rtdal006288Source0005 = `unquote <- function(expr, env) {
  if (is.pairlist(expr))
    as.pairlist(lapply(expr, unquote, env = env))
  else if (is.call(expr)) {
    if (is_bangbang(expr)) {
      eval(get_bangbang(expr), env)
    } else {
      as.call(lapply(expr, unquote, env = env))
    }
  }
  else expr
}`

const rtdal006288Source0008 = `is_literal <- function(x) {
  switch(typeof(x),
         character = , double = , integer = ,
         logical =   TRUE,
         list = all(map_lgl(x, is_literal)),
         call =      {
           if (is_call_vec(x))
             all(map_lgl(call_args(x), is_literal, TRUE))
           else
             FALSE
         },
         FALSE
  )
}`

const rtdal006288Source0009 = `expr_type <- function(x) {
  if (is.symbol(x)) {
    "symbol"
  } else if (is.call(x)) {
    "call"
  } else if (is_literal(x)) {
    "constant"
  } else {
    typeof(x)
  }
}`

const rtdal006288Source0010 = `switch_expr <- function(x, ...) {
  switch(expr_type(x), ...,
         stop("cannot handle type '", typeof(x), "'", call. = FALSE))
}`

const rtdal006288Source0013 = `all_calls_r <- function(x) {
  switch_expr(x,
              constant = ,
              symbol =   character(),
              call =     {
                fname <- paste0(x[[1]])
                children <- unlist(lapply(as.list(x[-1]), all_calls))
                c(fname, children)
              })
}`

const rtdal006288Source0015 = `new_env <- function(..., parent_env = NULL) {
  dots <- list(...)
  # default parent_env is taken from global parent env
  if (is.null(parent_env)) {
    parent_env <- emptyenv()
  }
  # register all elements in new env
  list2env(dots, envir = NULL, parent = parent_env, hash = TRUE)
}`

