const rtdal006289Source0001 = `cql2 <- function(expr, lang = NULL, crs = NULL) {
  cql2_update_ident_env(expr)
  # create cql2 object
  obj <- structure(list(), class = c("cql2", "list"))
  cql2_filter(obj) <- cql2_eval(expr)
  cql2_lang(obj) <- lang
  cql2_crs(obj) <- crs

  class(obj) <- c(lang[[1]], "cql2", "list")
  obj
}`

