const rtdal006305Source0001 = `preview_plot <- function(url) {
  preview_check(url)
  img <- preview_read_file(url)
  plot(1:10, ty = "n", axes = F, xlab = "", ylab = "")
  grid::grid.raster(img)
}`

const rtdal006305Source0003 = `preview_switch <- function(url, ...) {
  type <- preview_file_type(url)
  switch(type, ..., .error("File type '%s' not supported", type))
}`

const rtdal006305Source0004 = "preview_check <- function(url) {\n  preview_switch(\n    url,\n    png = if (!requireNamespace(\"png\", quietly = TRUE))\n      .error(paste(\n        \"This function requires `png` package. Please, use\",\n        \"install.packages('png').\"\n      ))\n    ,\n    jpeg = if (!requireNamespace(\"jpeg\", quietly = TRUE))\n      .error(paste(\n        \"This function requires `jpeg` package. Please, use\",\n        \"install.packages('jpeg').\"\n      ))\n  )\n}"

const rtdal006305Source0005 = `preview_read_file <- function(url) {
  temp_file <- tempfile(fileext = paste0(".", preview_file_type(url)))
  on.exit(unlink(temp_file))
  make_get_request(
    url = url,
    httr::write_disk(path = temp_file, overwrite = TRUE),
    error_msg = "Error while downloading"
  )
  preview_switch(
    url,
    png = png::readPNG(temp_file),
    jpeg = jpeg::readJPEG(temp_file)
  )
}`

