const rtdal006322Source0002 = "test_that(\"doc_conformance Test 7\", {\n  skip_if({\n    httr::http_error(httr::HEAD(\"https://cql2test.ldproxy.net/ne110m4cql2\"))\n  }, \"Test server is offline\")\n  q <- stac(base_url = \"https://cql2test.ldproxy.net/ne110m4cql2\",\n                   force_version = \"0.9.0\")\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME == \"Luxembourg\"\n    ),\n    expected_number = 1\n  )\n\n  req <- stac(\"https://planetarycomputer.microsoft.com/api/stac/v1\") %>%\n      stac_search(limit = 5)\n\n  polygon <- list(\n    type = \"Polygon\",\n    coordinates = list(\n      matrix(c(-62.34499836, -8.57414572,\n               -62.18858174, -8.57414572,\n               -62.18858174, -8.15351185,\n               -62.34499836, -8.15351185,\n               -62.34499836, -8.57414572),\n             ncol = 2, byrow = TRUE)\n    )\n  )\n  # 'S_INTERSECTS' spatial operator with polygon and geometry property\n  res <- req %>%\n    ext_filter(collection == \"sentinel-2-l2a\" &&\n                 s_intersects(geometry, {{polygon}}) &&\n                 datetime > \"2019-01-01\" &&\n                 datetime < \"2019-02-02\")\n  res <- post_request(res)\n\n  expect_s3_class(res, \"doc_items\")\n  res2 <- items_next(res)\n  expect_s3_class(res2, \"doc_items\")\n  expect_equal(object = items_length(res2), expected = items_length(res))\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME >= \"Luxembourg\"\n    ),\n    expected_number = 84\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME > \"Luxembourg\"\n    ),\n    expected_number = 83\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME <= \"Luxembourg\"\n    ),\n    expected_number = 94\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME < \"Luxembourg\"\n    ),\n    expected_number = 93\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      NAME != \"Luxembourg\"\n    ),\n    expected_number = 176\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST == 37589262\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST >= 37589262\n    ),\n    expected_number = 39\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST > 37589262\n    ),\n    expected_number = 38\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST <= 37589262\n    ),\n    expected_number = 139\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST < 37589262\n    ),\n    expected_number = 138\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_admin_0_countries\")),\n      POP_EST != 37589262\n    ),\n    expected_number = 176\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !is_null(name)\n    ),\n    expected_number = 243\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      is_null(name)\n    ),\n    expected_number = 0\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      name == 'København'\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !is_null(start)\n    ),\n    expected_number = 3\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !is_null(`\"date\"`)\n    ),\n    expected_number = 3\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      is_null(`\"date\"`)\n    ),\n    expected_number = 240\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` == date('2022-04-16')\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` >= date('2022-04-16')\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` > date('2022-04-16')\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` <= date('2022-04-16')\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` < date('2022-04-16')\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` != date('2022-04-16')\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      start == timestamp('2022-04-16T10:13:19Z')\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      boolean == TRUE\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      boolean == FALSE\n    ),\n    expected_number = 1\n  )\n})"

const rtdal006322Source0003 = "test_that(\"doc_conformance Test 12\", {\n  skip_if({\n    httr::http_error(httr::HEAD(\"https://cql2test.ldproxy.net/ne110m4cql2\"))\n  }, \"Test server is offline\")\n  q <- stac(base_url = \"https://cql2test.ldproxy.net/ne110m4cql2\",\n                   force_version = \"0.9.0\")\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      name %like% \"B_r%\"\n    ),\n    expected_number = 3\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !name %like% \"B_r%\"\n    ),\n    expected_number = 240\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      between(pop_other, 1000000, 3000000)\n    ),\n    expected_number = 75\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !between(pop_other, 1000000, 3000000)\n    ),\n    expected_number = 168\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      name %in% c('Kiev','kobenhavn','Berlin','athens','foo')\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !name %in% c('Kiev','kobenhavn','Berlin','athens','foo')\n    ),\n    expected_number = 241\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      pop_other %in% c(1038288,1611692,3013258,3013257,3013259)\n    ),\n    expected_number = 3\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !pop_other %in% c(1038288,1611692,3013258,3013257,3013259)\n    ),\n    expected_number = 240\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      `\"date\"` %in% c(date('2021-04-16'), date('2022-04-16'),\n                      date('2022-04-18'))\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !`\"date\"` %in% c(date('2021-04-16'), date('2022-04-16'),\n                       date('2022-04-18'))\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      start %in% c(timestamp('2022-04-16T10:13:19Z'))\n    ),\n    expected_number = 1\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !start %in% c(timestamp('2022-04-16T10:13:19Z'))\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      boolean %in% c(TRUE)\n    ),\n    expected_number = 2\n  )\n\n  conformance_test(\n    q = ext_filter(\n      items(collections(q, \"ne_110m_populated_places_simple\")),\n      !boolean %in% c(FALSE)\n    ),\n    expected_number = 2\n  )\n})"

