const rtdal006334Source0001 = `s2_geog_point <- function(longitude, latitude) {
  wk::wk_handle(wk::xy(longitude, latitude), s2_geography_writer())
}`

const rtdal006334Source0002 = `s2_make_line <- function(longitude, latitude, feature_id = 1L) {
  wk::wk_handle(
    wk::xy(longitude, latitude),
    wk::wk_linestring_filter(
      s2_geography_writer(),
      feature_id = as.integer(feature_id)
    )
  )
}`

const rtdal006334Source0003 = `s2_make_polygon <- function(longitude, latitude, feature_id = 1L, ring_id = 1L,
                            oriented = FALSE, check = TRUE) {
  wk::wk_handle(
    wk::xy(longitude, latitude),
    wk::wk_polygon_filter(
      s2_geography_writer(oriented = oriented, check = check),
      feature_id = as.integer(feature_id),
      ring_id = as.integer(ring_id)
    )
  )
}`

const rtdal006334Source0004 = `s2_geog_from_text <- function(wkt_string, oriented = FALSE, check = TRUE,
                              planar = FALSE,
                              tessellate_tol_m = s2_tessellate_tol_default()) {
  attributes(wkt_string) <- NULL
  wkt <- wk::new_wk_wkt(wkt_string, geodesic = TRUE)
  wk::validate_wk_wkt(wkt)

  wk::wk_handle(
    wkt,
    s2_geography_writer(
      oriented = oriented,
      check = check,
      tessellate_tol = if (planar) {
        tessellate_tol_m / s2_earth_radius_meters()
      } else {
        Inf
      }
    )
  )
}`

const rtdal006334Source0005 = `s2_geog_from_wkb <- function(wkb_bytes, oriented = FALSE, check = TRUE,
                             planar = FALSE,
                             tessellate_tol_m = s2_tessellate_tol_default()) {
  attributes(wkb_bytes) <- NULL
  wkb <- wk::new_wk_wkb(wkb_bytes)
  wk::validate_wk_wkb(wkb)

  wk::wk_handle(
    wkb,
    s2_geography_writer(
      oriented = oriented,
      check = check,
      tessellate_tol = if (planar) {
        tessellate_tol_m / s2_earth_radius_meters()
      } else {
        Inf
      }
    )
  )
}`

const rtdal006334Source0006 = `s2_as_text <- function(x, precision = 16, trim = TRUE,
                       planar = FALSE,
                       tessellate_tol_m = s2_tessellate_tol_default()) {
  wkt <- wk::wk_handle(
    as_s2_geography(x),
    wk::wkt_writer(precision = precision, trim = trim),
    s2_tessellate_tol = if (planar) {
      tessellate_tol_m / s2_earth_radius_meters()
    } else {
      Inf
    }
  )

  attributes(wkt) <- NULL
  wkt
}`

const rtdal006334Source0007 = `s2_as_binary <- function(x, endian = wk::wk_platform_endian(),
                         planar = FALSE,
                         tessellate_tol_m = s2_tessellate_tol_default()) {
  structure(
    wk::wk_handle(
      as_s2_geography(x),
      wk::wkb_writer(endian = endian),
      s2_tessellate_tol = if (planar) {
        tessellate_tol_m / s2_earth_radius_meters()
      } else {
        Inf
      }
    ),
    class = "blob"
  )
}`

