const rtdal006348Source0001 = `.onLoad <- function(...) {
  # dynamically register vctrs dependencies
  for (cls in c("s2_geography", "s2_cell", "s2_cell_union")) {
    s3_register("vctrs::vec_proxy", cls)
    s3_register("vctrs::vec_restore", cls)
    s3_register("vctrs::vec_ptype_abbr", cls)
  }

  s3_register("bit64::as.integer64", "s2_cell")
}`

const rtdal006348Source0002 = "s3_register <- function(generic, class, method = NULL) {\n  stopifnot(is.character(generic), length(generic) == 1)\n  stopifnot(is.character(class), length(class) == 1)\n\n  pieces <- strsplit(generic, \"::\")[[1]]\n  stopifnot(length(pieces) == 2)\n  package <- pieces[[1]]\n  generic <- pieces[[2]]\n\n  caller <- parent.frame()\n\n  get_method_env <- function() {\n    top <- topenv(caller)\n    if (isNamespace(top)) {\n      asNamespace(environmentName(top))\n    } else {\n      caller\n    }\n  }\n  get_method <- function(method, env) {\n    if (is.null(method)) {\n      get(paste0(generic, \".\", class), envir = get_method_env())\n    } else {\n      method\n    }\n  }\n\n  method_fn <- get_method(method)\n  stopifnot(is.function(method_fn))\n\n  # Always register hook in case package is later unloaded & reloaded\n  setHook(\n    packageEvent(package, \"onLoad\"),\n    function(...) {\n      ns <- asNamespace(package)\n\n      # Refresh the method, it might have been updated by `devtools::load_all()`\n      method_fn <- get_method(method)\n\n      registerS3method(generic, class, method_fn, envir = ns)\n    }\n  )\n\n  # Avoid registration failures during loading (pkgload or regular)\n  if (!isNamespaceLoaded(package)) {\n    return(invisible())\n  }\n\n  envir <- asNamespace(package)\n\n  # Only register if generic can be accessed\n  if (exists(generic, envir)) {\n    registerS3method(generic, class, method_fn, envir = envir)\n  }\n\n  invisible()\n}"

