const rtdal006381Source0001 = "as_class <- function(x, arg = deparse(substitute(x))) {\n  error_base <- sprintf(\"Can't convert `%s` to a valid class. \", arg)\n\n  if (is_foundation_class(x)) {\n    x\n  } else if (is.null(x)) {\n    # NULL is handled specially because you can't assign a class to it,\n    # so it can't be wrapped in new_base_class\n    x\n  } else if (isS4(x)) {\n    S4_to_S7_class(x, error_base)\n  } else {\n    msg <- sprintf(\"Class specification must be an S7 class object, the result of `new_S3_class()`, an S4 class object, or a base class, not a %s.\", obj_desc(x))\n    stop(paste0(error_base, msg), call. = FALSE)\n  }\n}"

const rtdal006381Source0003 = "class_type <- function(x) {\n  if (is.null(x)) {\n    \"NULL\"\n  } else if (is_class_missing(x)) {\n    \"missing\"\n  } else if (is_class_any(x)) {\n    \"any\"\n  } else if (is_base_class(x)) {\n    \"S7_base\"\n  } else if (is_class(x)) {\n    \"S7\"\n  } else if (is_union(x)) {\n    \"S7_union\"\n  } else if (is_S3_class(x)) {\n    \"S7_S3\"\n  } else if (is_S4_class(x)) {\n    \"S4\"\n  } else {\n    stop(\"`x` is not standard S7 class\", call. = FALSE)\n  }\n}"

const rtdal006381Source0005 = `class_construct <- function(.x, ...) {
  class_constructor(.x)(...)
}`

const rtdal006381Source0006 = "class_construct_expr <- function(.x, envir = NULL, package = NULL) {\n  f <- class_constructor(.x)\n\n  # For S7 class constructors with a non-NULL @package property\n  # Instead of inlining the full class definition, use either\n  # `pkgname::classname()` or `classname()`\n  if (is_class(f) && !is.null(f@package)) {\n    # Check if the class can be resolved as a bare symbol without pkgname::\n    # Note: During package build, using pkg::class for a package's own symbols\n    # will raise an error from `::`.\n    if (identical(package, f@package)) {\n      return(call(f@name))\n    } else {\n      # namespace the pkgname::classname() call\n      cl <- as.call(list(quote(`::`), as.name(f@package), as.name(f@name)))\n\n      # check the call evaluates to f.\n      # This will error if package is not installed or object is not exported.\n      f2 <- eval(cl, baseenv())\n      if (!identical(f, f2)) {\n        msg <- sprintf(\n          \"`%s::%s` is not identical to the class with the same @package and @name properties\",\n          f@package, f@name\n        )\n        stop(msg, call. = FALSE)\n      }\n      return(as.call(list(cl)))\n    }\n  }\n\n  # If the constructor is a closure wrapping a simple expression, try\n  # to extract the expression\n  # (mostly for nicer printing and introspection.)\n\n  # can't unwrap if the closure is potentially important\n  # (this can probably be relaxed to allow additional environments)\n  fe <- environment(f)\n  if (!identical(fe, baseenv())) {\n    return(as.call(list(f)))\n  }\n\n  # special case for `class_missing`\n  if (identical(body(f) -> fb, quote(expr =))) {\n    return(quote(expr =))\n  }\n\n  # `new_object()` must be called from the class constructor, can't\n  # be safely unwrapped\n  if (\"new_object\" %in% all.names(fb)) {\n    return(as.call(list(f)))\n  }\n\n  # maybe unwrap body if it is a single expression wrapped in `{`\n  if (length(fb) == 2L && identical(fb[[1L]], quote(`{`)))\n    fb <- fb[[2L]]\n\n  # If all the all the work happens in the promise to the `.data` arg,\n  # return the `.data` expression.\n  ff <- formals(f)\n  if ((identical(fb, quote(.data))) &&\n      identical(names(ff), \".data\")) {\n    return(ff$.data)\n  }\n\n  # if all the work happens in the function body, return the body.\n  if (is.null(ff)) {\n    return(fb)\n  }\n\n  #else, return a call to the constructor\n  as.call(list(f))\n}"

const rtdal006381Source0007 = `class_constructor <- function(.x) {
  switch(class_type(.x),
         any = ,
         NULL = new_function(env = baseenv()),
         missing = new_function(, quote(expr =), baseenv()),
         S4 = function(...) methods::new(.x, ...),
         S7 = .x,
         S7_base = .x$constructor,
         S7_union = class_constructor(.x$classes[[1]]),
         S7_S3 = .x$constructor,
         stop(sprintf("Can't construct %s", class_friendly(.x)), call. = FALSE)
  )
}`

const rtdal006381Source0008 = `class_validate <- function(class, object) {
  validator <- switch(class_type(class),
    S4 = methods::validObject,
    S7 = class@validator,
    S7_base = class$validator,
    S7_S3 = class$validator,
    NULL
  )

  if (is.null(validator)) {
    NULL
  } else {
    validator(object)
  }
}`

const rtdal006381Source0010 = `class_dispatch <- function(x) {
  if (is_class(x) && x@name == "S7_object") {
    return("S7_object")
  }

  switch(class_type(x),
    NULL = "NULL",
    missing = "MISSING",
    any = character(),
    S4 = S4_class_dispatch(methods::extends(x)),
    S7 = c(S7_class_name(x), class_dispatch(x@parent)),
    S7_base = c(x$class, "S7_object"),
    S7_S3 = c(x$class, "S7_object"),
    stop("Unsupported")
  )
}`

const rtdal006381Source0012 = `class_deparse <- function(x) {
  switch(class_type(x),
    "NULL" = "NULL",
    missing = "class_missing",
    any = "class_any",
    S4 = as.character(x@className),
    S7 = S7_class_name(x),
    S7_base = paste0("class_", x$class),
    S7_union = {
      classes <- vcapply(x$classes, class_deparse)
      paste0("new_union(", paste(classes, collapse = ", "), ")")
    },
    S7_S3 = paste0("new_S3_class(", deparse1(x$class), ")"),
  )
}`

const rtdal006381Source0013 = `class_inherits <- function(x, what) {
  switch(class_type(what),
    "NULL" = is.null(x),
    missing = FALSE,
    any = TRUE,
    S4 = isS4(x) && methods::is(x, what),
    S7 = inherits(x, "S7_object") && inherits(x, S7_class_name(what)),
    S7_base = what$class == base_class(x),
    S7_union = any(vlapply(what$classes, class_inherits, x = x)),
    # This is slightly too crude as we really want them to be in the same
    # order and contiguous, but it's probably close enough for practical
    # purposes
    S7_S3 = !isS4(x) && all(what$class %in% class(x)),
  )
}`

const rtdal006381Source0014 = `obj_type <- function(x) {
  if (identical(x, quote(expr = ))) {
    "missing"
  } else if (inherits(x, "S7_object")) {
    "S7"
  } else if (isS4(x)) {
    "S4"
  } else if (is.object(x)) {
    "S3"
  } else {
    "base"
  }
}`

const rtdal006381Source0016 = `obj_dispatch <- function(x) {
  switch(obj_type(x),
    missing = "MISSING",
    base = base_class(x),
    S3 = class(x),
    S4 = S4_class_dispatch(methods::getClass(class(x))),
    S7 = class(x) # = class_dispatch(S7_class(x))
  )
}`

