const rtdal006382Source0001 = `new_class <- function(
    name,
    parent = S7_object,
    package = topNamespaceName(parent.frame()),
    properties = list(),
    abstract = FALSE,
    constructor = NULL,
    validator = NULL) {

  check_name(name)

  parent <- as_class(parent)

  # Don't check arguments for S7_object
  if (!is.null(parent)) {
    check_can_inherit(parent)
    if (!is.null(package)) {
      check_name(package)
    }
    if (!is.null(constructor)) {
      check_S7_constructor(constructor)
    }
    if (!is.null(validator)) {
      check_function(validator, alist(self = ))
    }
    if (abstract && (!is_class(parent) || !(parent@abstract || parent@name == "S7_object"))) {
      stop("Abstract classes must have abstract parents")
    }
  }

  # Combine properties from parent, overriding as needed
  all_props <- attr(parent, "properties", exact = TRUE) %||% list()
  new_props <- as_properties(properties)
  check_prop_names(new_props)
  all_props[names(new_props)] <- new_props

  if (is.null(constructor)) {
    constructor <- new_constructor(parent, all_props,
                                   envir = parent.frame(),
                                   package = package)
  }

  object <- constructor
  # Must synchronise with prop_names
  attr(object, "name") <- name
  attr(object, "parent") <- parent
  attr(object, "package") <- package
  attr(object, "properties") <- all_props
  attr(object, "abstract") <- abstract
  attr(object, "constructor") <- constructor
  attr(object, "validator") <- validator
  class(object) <- c("S7_class", "S7_object")

  global_variables(names(all_props))
  object
}`

const rtdal006382Source0004 = "check_S7_constructor <- function(constructor) {\n  if (!is.function(constructor)) {\n    stop(\"`constructor` must be a function\", call. = FALSE)\n  }\n\n  method_call <- find_call(body(constructor), quote(new_object), packageName())\n  if (is.null(method_call)) {\n    stop(\"`constructor` must contain a call to `new_object()`\", call. = FALSE)\n  }\n}"

const rtdal006382Source0005 = `print.S7_class <- function(x, ...) {
  props <- x@properties
  if (length(props) > 0) {
    prop_names <- format(names(props))
    prop_types <- format(vcapply(props, function(x) class_desc(x$class)))
    prop_fmt <- paste0(" $ ", prop_names, ": ", prop_types, "\n", collapse = "")
  } else {
    prop_fmt <- ""
  }

  cat(
    sprintf(
      paste0(
        "%s%s class\n",
        "@ parent     : %s\n",
        "@ constructor: %s\n",
        "@ validator  : %s\n",
        "@ properties :\n%s"
      ),
      class_desc(x),
      if (x@abstract) " abstract" else "",
      class_desc(x@parent),
      show_function(x@constructor, constructor = TRUE),
      if (!is.null(x@validator)) show_function(x@validator) else "<NULL>",
      prop_fmt
    ),
    sep = ""
  )
  invisible(x)
}`

const rtdal006382Source0006 = `str.S7_class <- function(object, ..., nest.lev = 0) {
  cat(if (nest.lev > 0) " ")
  cat("<", paste0(class_dispatch(object), collapse = "/"), "> constructor", sep = "")
  cat("\n")

  if (nest.lev == 0) {
    str_nest(props(object), "@", ..., nest.lev = nest.lev)
  }
}`

const rtdal006382Source0007 = `c.S7_class <- function(...) {
  msg <- "Can not combine S7 class objects"
  stop(msg, call. = FALSE)
}`

const rtdal006382Source0009 = "check_can_inherit <- function(x, arg = deparse(substitute(x))) {\n  if (!can_inherit(x)) {\n    msg <- sprintf(\n      \"`%s` must be an S7 class, S3 class, or base type, not %s.\",\n      arg,\n      class_friendly(x)\n    )\n    stop(msg, call. = FALSE)\n  }\n\n  if (is_base_class(x) && x$class == \"environment\") {\n    stop(\"Can't inherit from an environment.\", call. = FALSE)\n  }\n}"

const rtdal006382Source0011 = "new_object <- function(.parent, ...) {\n  class <- sys.function(-1)\n  if (!inherits(class, \"S7_class\")) {\n    stop(\"`new_object()` must be called from within a constructor\")\n  }\n  if (class@abstract) {\n    msg <- sprintf(\"Can't construct an object from abstract class <%s>\", class@name)\n    stop(msg)\n  }\n\n  # force .parent before ...\n  # TODO: Some type checking on `.parent`?\n  object <- .parent\n\n  args <- list(...)\n  if (\"\" %in% names2(args)) {\n    stop(\"All arguments to `...` must be named\")\n  }\n\n  has_setter <- vlapply(class@properties[names(args)], prop_has_setter)\n\n  attrs <- c(\n    list(class = class_dispatch(class), S7_class = class),\n    args[!has_setter],\n    attributes(object)\n  )\n  attrs <- attrs[!duplicated(names(attrs))]\n  attributes(object) <- attrs\n\n  # invoke custom property setters\n  prop_setter_vals <- args[has_setter]\n  for (name in names(prop_setter_vals))\n    prop(object, name, check = FALSE) <- prop_setter_vals[[name]]\n\n  # Don't need to validate if parent class already validated,\n  # i.e. it's a non-abstract S7 class\n  parent_validated <- inherits(class@parent, \"S7_object\") && !class@parent@abstract\n  validate(object, recursive = !parent_validated)\n\n  object\n}"

const rtdal006382Source0012 = `print.S7_object <- function(x, ...) {
  str(x, ...)
  invisible(x)
}`

const rtdal006382Source0013 = `str.S7_object <- function(object, ..., nest.lev = 0) {
  cat(if (nest.lev > 0) " ")
  cat(obj_desc(object))

  if (!is_S7_type(object)) {
    if (!typeof(object) %in% c("numeric", "integer", "character", "double"))
      cat(" ")

    attrs <- attributes(object)
    if (is.environment(object)) {
      attributes(object) <- NULL
    } else {
      attributes(object) <- list(names = names(object), dim = dim(object))
    }

    str(object, nest.lev = nest.lev)
    attributes(object) <- attrs
  } else {
    cat("\n")
  }

  str_nest(props(object), "@", ..., nest.lev = nest.lev)
}`

const rtdal006382Source0015 = `check_prop_names <- function(properties, error_call = sys.call(-1L)) {
  # these attributes have special C handlers in base R
  forbidden <- c("names", "dim", "dimnames", "class",
                 "tsp", "comment", "row.names", "...")
  forbidden <- intersect(forbidden, names(properties))
  if (length(forbidden)) {
    msg <- paste0("property can't be named: ",
                  paste0(forbidden, collapse = ", "))
    stop(simpleError(msg, error_call))
  }
}`

