const rtdal006392Source0002 = `method_explain <- function(generic, class = NULL, object = NULL) {
  check_is_S7(generic, S7_generic)
  dispatch <- as_dispatch(generic, class = class, object = object)
  dispatch <- lapply(dispatch, c, "ANY")

  grid <- as.matrix(rev(do.call("expand.grid", rev(dispatch))))
  colnames(grid) <- generic@dispatch_args

  names <- paste0("[", grid, "]")
  dim(names) <- dim(grid)
  methods <- apply(names, 1, paste, collapse = ", ")

  has_method <- function(dispatches, env) {
    for (x in dispatches) {
      env <- env[[x]]
    }
    is.function(env)
  }
  exists <- apply(grid, 1, has_method, env = generic@methods)

  label <- ifelse(exists, "* ", "  ")
  if (any(exists)) {
    label[which(exists)[[1]]] <- "->"
  }

  cat(paste0(label, " ", generic@name, "(", methods, ")\n"), sep = "")
  invisible()
}`

const rtdal006392Source0003 = "as_dispatch <- function(generic, class = NULL, object = NULL) {\n  if (!is.null(class) && is.null(object)) {\n    signature <- as_signature(class, generic)\n    is_union <- vlapply(signature, is_union)\n    if (any(is_union)) {\n      stop(\"Can't dispatch on unions; must be a concrete type\")\n    }\n\n    lapply(signature, class_dispatch)\n  } else if (!is.null(object) && is.null(class)) {\n    n <- generic_n_dispatch(generic)\n    if (n == 1) {\n      object <- list(object)\n    } else {\n      check_signature_list(object, n = n, arg = \"object\")\n    }\n    lapply(object, obj_dispatch)\n  } else {\n    stop(\"Must supply exactly one of `class` and `object`\", call. = FALSE)\n  }\n}"

const rtdal006392Source0004 = `error_types <- function(generic, class = NULL, object = NULL) {
  if (is.null(class)) {
    n <- generic_n_dispatch(generic)
    if (n == 1) {
      types <- list(obj_desc(object))
    } else {
      types <- vcapply(object, obj_desc)
    }
  } else {
    signature <- as_signature(class, generic)
    types <- vcapply(signature, class_desc)
  }
  names(types) <- generic@dispatch_args
  types
}`

