const rtdal006395Source0001 = `new_property <- function(class = class_any,
                         getter = NULL,
                         setter = NULL,
                         validator = NULL,
                         default = NULL,
                         name = NULL) {
  class <- as_class(class)
  check_prop_default(default, class)

  if (!is.null(getter)) {
    check_function(getter, alist(self = ))
  }
  if (!is.null(setter)) {
    check_function(setter, alist(self = , value = ))
  }
  if (!is.null(validator)) {
    check_function(validator, alist(value = ))
  }

  out <- list(
    name = name,
    class = class,
    getter = getter,
    setter = setter,
    validator = validator,
    default = default
  )
  class(out) <- "S7_property"

  out
}`

const rtdal006395Source0003 = `stop.parent <- function(..., call = sys.call(-2)) {
  stop(simpleError(.makeMessage(...), call))
}`

const rtdal006395Source0005 = `print.S7_property <- function(x, ...) {
  cat("<S7_property> \n")
  str_nest(x, "$", ...)
}`

const rtdal006395Source0006 = `str.S7_property <- function(object, ..., nest.lev = 0) {
  cat(if (nest.lev > 0) " ")
  print(object, ..., nest.lev = nest.lev)
}`

const rtdal006395Source0009 = "propr <- function(object, name) {\n  # reference implementation of `prop()` implemented in R\n  check_is_S7(object)\n\n  if (!prop_exists(object, name)) {\n    stop(prop_error_unknown(object, name), call. = FALSE)\n  } else {\n    prop_val(object, name)\n  }\n}"

const rtdal006395Source0011 = `prop_val <- function(object, name) {
  val <- attr(object, name, exact = TRUE)
  if (is.null(val)) {
    prop <- prop_obj(object, name)
    if (!is.null(prop$getter)) {
      val <- prop$getter(object)
    }
  }
  val
}`

const rtdal006395Source0014 = "`propr<-` <- local({\n    # reference implementation of `prop<-()` implemented in R\n  # This flag is used to avoid infinite loops if you are assigning a property from a setter function\n  setter_property <- NULL\n\n  function(object, name, check = TRUE, value) {\n    check_is_S7(object)\n\n    prop <- prop_obj(object, name)\n    if (is.null(prop)) {\n      stop(prop_error_unknown(object, name), call. = FALSE)\n    }\n\n    if (!is.null(prop$getter) && is.null(prop$setter)) {\n      msg <- sprintf(\"Can't set read-only property %s@%s\", obj_desc(object), name)\n      stop(msg, call. = FALSE)\n    }\n\n    if (!is.null(prop$setter) && !identical(setter_property, name)) {\n      setter_property <<- name\n      on.exit(setter_property <<- NULL, add = TRUE)\n      object <- prop$setter(object, value)\n    } else {\n      if (isTRUE(check)) {\n        error <- prop_validate(prop, value, object)\n        if (!is.null(error)) {\n          stop(error, call. = FALSE)\n        }\n      }\n\n      attr(object, name) <- value\n    }\n\n    if (isTRUE(check) && is.null(setter_property)) {\n      validate(object, properties = FALSE)\n    }\n\n    invisible(object)\n  }\n})"

const rtdal006395Source0018 = `prop_validate <- function(prop, value, object = NULL) {
  if (!class_inherits(value, prop$class)) {
    return(sprintf("%s must be %s, not %s",
      prop_label(object, prop$name),
      class_desc(prop$class),
      obj_desc(value)
    ))
  }

  if (is.null(validator <- prop$validator)) {
    return(NULL)
  }

  val <- validator(value)
  if (is.null(val)) {
    return(NULL)
  }

  if (is.character(val)) {
    if (length(val)) {
      return(paste0(prop_label(object, prop$name), " ", val))
    } else {
      return(NULL)
    }
  }

  stop(sprintf(
    "%s validator must return NULL or a character, not <%s>.",
    prop_label(object, prop$name), typeof(val)
  ))
}`

const rtdal006395Source0019 = `prop_label <- function(object, name) {
  sprintf("%s@%s", if (!is.null(object)) obj_desc(object) else "", name)
}`

const rtdal006395Source0022 = `prop_names <- function(object) {
  check_is_S7(object)

  if (inherits(object, "S7_class")) {
    # S7_class isn't a S7_class (somewhat obviously) so we fake the property names
    c("name", "parent", "package", "properties", "abstract", "constructor", "validator")
  } else {
    class <- S7_class(object)
    props <- attr(class, "properties", exact = TRUE)
    if (length(props) == 0) {
      character()
    } else {
      names(props)
    }
  }
}`

const rtdal006395Source0023 = ".AtNames.S7_object <- function(x, pattern = \"\") {\n  # utils::findMatches gives `R CMD check` warning on current r-devel\n  asNamespace(\"utils\")$findMatches(pattern, prop_names(x))\n}"

const rtdal006395Source0025 = `props <- function(object, names = prop_names(object)) {
  check_is_S7(object)
  if (length(names) == 0) {
    structure(list(), names = character(0))
  } else {
    setNames(lapply(names, prop, object = object), names)
  }
}`

const rtdal006395Source0026 = "`props<-` <- function(object, check = TRUE, value) {\n  if (check) {\n    check_is_S7(object)\n    stopifnot(is.list(value))\n  }\n\n  for (name in names(value)) {\n    prop(object, name, check = FALSE) <- value[[name]]\n  }\n\n  if (check) {\n    validate(object)\n  }\n\n  object\n}"

const rtdal006395Source0027 = `set_props <- function(object, ..., .check = TRUE) {
  props(object, check = .check) <- list(...)
  object
}`

const rtdal006395Source0028 = "as_properties <- function(x) {\n  if (length(x) == 0) {\n    return(list())\n  }\n\n  if (!is.list(x)) {\n    stop(\"`properties` must be a list\", call. = FALSE)\n  }\n\n  out <- Map(as_property, x, names2(x), seq_along(x))\n  names(out) <- vapply(out, function(x) x$name, FUN.VALUE = character(1))\n\n  if (anyDuplicated(names(out))) {\n    stop(\"`properties` names must be unique\", call. = FALSE)\n  }\n\n  out\n}"

const rtdal006395Source0029 = "as_property <- function(x, name, i) {\n\n  if (is_property(x)) {\n    if (name == \"\") {\n      if (is.null(x$name)) {\n        msg <- sprintf(\"`properties[[%i]]` must have a name or be named.\", i)\n        stop(msg, call. = FALSE)\n      }\n    } else {\n      x$name <- name\n    }\n    x\n  } else {\n    if (name == \"\") {\n      msg <- sprintf(\"`properties[[%i]]` must be named.\", i)\n      stop(msg, call. = FALSE)\n    }\n\n    class <- as_class(x, arg = paste0(\"property$\", name))\n    new_property(x, name = name)\n  }\n}"

