const rtdal006396Source0001 = "new_S3_class <- function(class, constructor = NULL, validator = NULL) {\n  if (!is.character(class)) {\n    stop(\"`class` must be a character vector\", call. = FALSE)\n  }\n  if (!is.null(constructor)) {\n    check_S3_constructor(constructor)\n  } else {\n    constructor <- function(.data) {\n      stop(sprintf(\"S3 class <%s> doesn't have a constructor\", class[[1]]), call. = FALSE)\n    }\n  }\n\n  out <- list(\n    class = class,\n    constructor = constructor,\n    validator = validator\n  )\n  class(out) <- \"S7_S3_class\"\n  out\n}"

const rtdal006396Source0002 = `print.S7_S3_class <- function(x, ...) {
  cat("<S7_S3_class>: ", class_desc(x), "\n", sep = "")
  invisible(x)
}`

const rtdal006396Source0003 = `str.S7_S3_class <- function(object, ..., nest.lev = 0) {
  cat(if (nest.lev > 0) " ")
  print(object, ..., nest.lev = nest.lev)
}`

const rtdal006396Source0004 = "check_S3_constructor <- function(constructor) {\n  arg_names <- names(formals(constructor))\n  if (arg_names[[1]] != \".data\") {\n    stop(\"First argument to `constructor` must be .data\", call. = FALSE)\n  }\n  if (\"...\" %in% arg_names) {\n    stop(\"`constructor` can not use `...`\", call. = FALSE)\n  }\n}"

const rtdal006396Source0006 = `validate_factor <- function(self) {
  c(
    if (typeof(self) != "integer")
      "Underlying data must be an <integer>",
    if (!is.character(attr(self, "levels", TRUE)))
      "attr(, 'levels') must be a <character>",
    { rng <- range(0L, unclass(self)); NULL },
    if (rng[1] < 0L)
      "Underlying data must be all positive",
    if (rng[2] > length(attr(self, "levels", TRUE)))
      "Not enough 'levels' for underlying data"
  )
}`

const rtdal006396Source0007 = `validate_date <- function(self) {
  c(
    if (mode(self) != "numeric")
      "Underlying data must be numeric",
    if (!inherits(self, "Date"))
      "Underlying data must have class 'Date'"
  )
}`

const rtdal006396Source0008 = `validate_POSIXct <- function(self) {
  if (mode(self) != "numeric") {
    return("Underlying data must be numeric")
  }

  tz <- attr(self, "tz")
  if (!is.character(tz) || length(tz) != 1) {
    return("attr(, 'tz') must be a single string")
  }
}`

const rtdal006396Source0009 = `validate_POSIXlt <- function(self) {
  tryCatch({
    format(self) # calls valid_POSIXlt() in C
    invisible(NULL)
  }, error = function(e) conditionMessage(e))
}`

const rtdal006396Source0010 = `validate_data.frame <- function(self) {
  if (!is.list(self)) {
    return("Underlying data must be a <list>")
  }

  if (length(self) >= 1) {
    # Avoid materialising compact row names
    ns <- unique(c(lengths(self), .row_names_info(self, 2L)))
    if (length(ns) > 1) {
      return("All columns and row names must have the same length")
    }

    if (is.null(names(self))) {
      return("Underlying data must be named")
    }
  }
}`

const rtdal006396Source0012 = `validate_matrix <- function(self) {
  if (!is.matrix(self)) {
    # is.matrix() methods should only return TRUE if valid
    "is.matrix(self) is FALSE"
  } else if (!is.integer(dim(self)) || length(dim(self)) != 2L || !all(dim(self) >= 0L)) {
    "dim(self) must be a non-negative integer vector of length 2"
  } else if (!valid_dimnames(self)) {
    "dimnames(self) must be NULL or a length 2 list of either NULL or a character vector of length equal to its corresponding dimension"
  }
}`

const rtdal006396Source0014 = "validate_formula <- function(self) {\n  if (is.null(environment(self)))\n    return(\"environment(self) must be non-NULL\")\n  if (identical(self, stats::formula(NULL, environment(self)))) # weird NULL case\n    return(invisible(NULL))\n  if (!is.call(self) || !length(self) %in% 2:3 || unclass(self)[[1L]] != quote(`~`))\n    return(\"must be a call to `~` of length 2 or 3\")\n}"

const rtdal006396Source0020 = `class_data.frame <- new_S3_class("data.frame",
  constructor = function(.data = list(), row.names = NULL) {
    if (is.null(row.names)) {
      list2DF(.data)
    } else {
      out <- list2DF(.data, length(row.names))
      attr(out, "row.names") <- row.names
      out
    }
  },
  validator = validate_data.frame
)`

const rtdal006396Source0022 = `class_array <- new_S3_class("array",
  constructor = function(.data = logical(),
                         dim = base::dim(.data) %||% length(.data),
                         dimnames = base::dimnames(.data)) {
    array(.data, dim, dimnames)
  },
  validator = validate_array
)`

const rtdal006396Source0023 = `class_formula <- new_S3_class("formula",
  constructor = function(.data = NULL, env = parent.frame()) {
    stats::formula(.data, env = env)
  },
  validator = validate_formula
)`

